]

[
  {
    "find": "none of its CVEs were matched.",
    "replace": "none of the package's CVEs were matched.",
    "type": "unclear-reference",
    "reason": "The pronoun \"its\" could refer to the package or the generated CPE; naming the package removes the ambiguity."
  },
  {
    "find": "pinning it to `anthropic:claude_code`",
    "replace": "pinning the package to `anthropic:claude_code`",
    "type": "unclear-reference",
    "reason": "The pronoun \"it\" could refer to the rule or the package; the package is what the rule maps."
  },
  {
    "find": "The generated CPE is now `cpe:2.3:a:anthropic:claude_code:<version>:*:*:*:*:node.js:*:*`, which matches the NVD configurations I checked (CVE-2025-58764, CVE-2025-59536, CVE-2026-25722, CVE-2026-39861, CVE-2026-54316 all use `cpe:2.3:a:anthropic:claude_code:*:*:*:*:*:node.js:*:*` with a version range).",
    "replace": "The generated CPE is now `cpe:2.3:a:anthropic:claude_code:<version>:*:*:*:*:node.js:*:*`. It matches the NVD configurations I checked: CVE-2025-58764, CVE-2025-59536, CVE-2026-25722, CVE-2026-39861, and CVE-2026-54316 all use `cpe:2.3:a:anthropic:claude_code:*:*:*:*:*:node.js:*:*` with a version range.",
    "type": "hard-clause",
    "reason": "The original packs a long CVE list into a relative clause; splitting keeps the CPE claim and the evidence separate."
  },
  {
    "find": "Not included: the Homebrew `claude-code` cask.",
    "replace": "This change does not include the Homebrew `claude-code` cask.",
    "type": "telegraphic",
    "reason": "The colon label leaves the reader to infer the subject and verb; a full sentence states it directly."
  },
  {
    "find": "Homebrew software gets `target_sw=macos` in the generated CPE, and every claude_code CVE configuration I checked is pinned to `target_sw=node.js`, so",
    "replace": "Homebrew software gets `target_sw=macos` in the generated CPE. Every claude_code CVE configuration I checked is pinned to `target_sw=node.js`, so",
    "type": "hard-clause",
    "reason": "The original joins two independent facts and a consequence in one long sentence; splitting at the first clause makes the logic easier to follow."
  },
  {
    "find": "surface those CVEs",
    "replace": "match those CVEs",
    "type": "jargon",
    "reason": "\"Surface\" is a spatial metaphor here; the rule either matches CVEs or it does not."
  }
]

[
  {
    "find": "A process is an independent execution unit with its own isolated memory space, while a thread is a lightweight execution unit that exists within a process and shares its memory with other threads in the same process.",
    "replace": "A process is an independent execution unit with its own isolated memory space. A thread is a lightweight execution unit that exists within a process and shares its memory with other threads in the same process.",
    "type": "hard-clause",
    "reason": "It combines two definitions in one long contrast; splitting them gives each definition its own sentence."
  },
  {
    "find": "Spawning a process is comparatively expensive (new page tables, file descriptor tables, etc.), whereas thread creation and switching are cheaper.",
    "replace": "Spawning a process is comparatively expensive because it needs new page tables, file descriptor tables, and so on. Creating and switching threads is cheaper.",
    "type": "telegraphic",
    "reason": "The parenthetical list drops the verb and reads like a note; restoring 'because it needs' makes the reason a sentence."
  },
  {
    "find": "Inter-process communication requires explicit mechanisms (pipes, sockets, shared memory segments), while threads communicate through shared variables, necessitating synchronization primitives such as mutexes and semaphores.",
    "replace": "Inter-process communication requires explicit mechanisms such as pipes, sockets, and shared memory segments. Threads communicate through shared variables, so they need synchronization primitives such as mutexes and semaphores.",
    "type": "hard-clause",
    "reason": "The sentence chains a contrast and a participle with a parenthetical list; splitting it gives each side one clear job."
  },
  {
    "find": "It's worth noting that in CPython",
    "replace": "In CPython",
    "type": "redundant",
    "reason": "The phrase only announces that a point is coming and delays it."
  },
  {
    "find": "leverage",
    "replace": "use",
    "type": "jargon",
    "reason": "'Leverage' is business jargon here; the plain action is to use multiprocessing."
  }
]

[
  {
    "find": "Refactors spanning multiple packages land in a single commit, eliminating version-skew coordination.",
    "replace": "When a refactor spans multiple packages, you can make it in a single commit, so you no longer need to coordinate version skew.",
    "type": "hard-clause",
    "reason": "The reduced relative phrase and the result clause make the reader unpack who does what and why version coordination goes away."
  },
  {
    "find": "One CI configuration, one linting setup, consistent dependency versions.",
    "replace": "You have one CI configuration, one linting setup, and consistent dependency versions.",
    "type": "telegraphic",
    "reason": "The bullet is a fragment: it drops the verb and the conjunction in the list."
  },
  {
    "find": "Git performance at scale, code ownership mapping, and selective test execution all require dedicated effort.",
    "replace": "You need dedicated effort to make Git perform well at scale, to map code ownership, and to run selected tests.",
    "type": "buried-verb",
    "reason": "The actions are packed into noun phrases such as 'code ownership mapping' and 'selective test execution' instead of stated as verbs."
  },
  {
    "find": "a monorepo tends to pay dividends",
    "replace": "a monorepo tends to bring benefits",
    "type": "jargon",
    "reason": "'Pay dividends' is a business metaphor; the plain meaning is that it brings benefits."
  }
]

[
