[
  {
    "find": "We're thrilled to announce v2.4, packed with powerful new capabilities designed to supercharge your workflow!",
    "replace": "v2.4 adds new capabilities.",
    "type": "empty-words",
    "reason": "Uses hype words ('thrilled', 'powerful', 'supercharge') that add no concrete information."
  },
  {
    "find": "Seamlessly switch between environments using `--profile staging`.",
    "replace": "Switch between environments with `--profile staging`.",
