    "reason": "The sentence is long, drops 'that' before the relative clause, wedges an aside between subject and verb, and uses an ambiguous 'which'; splitting it and adding 'that' makes the cause and test condition clear."
  },
  {
    "find": "DB commit acknowledgement handling",
    "replace": "code that handles the DB commit acknowledgement",
    "type": "noun-stack",
    "reason": "Four nouns are stacked as a modifier; unpacking the action with a verb makes the order change clear."
  },
  {
    "find": "unblocks the release-train critical path",
    "replace": "removes a blocker from the critical path for the release train",
    "type": "jargon",
    "reason": "'Unblocks' hides the plain action, and the stacked 'release-train critical path' makes the reader decode which path belongs to what."
  },
  {
    "find": "flake-rate-driven CI retry overhead",
    "replace": "CI retry overhead caused by test flakiness",
    "type": "noun-stack",
    "reason": "The stacked modifiers hide that the overhead is CI retries caused by test flakiness."
  }
]

[
  {
    "find": "The load factor, defined as `n / m`, captures the occupancy-driven collision probability growth the table structure experiences as insertions accumulate.",
    "replace": "The load factor, defined as `n / m`, measures how full the table is. As insertions accumulate, higher occupancy makes collisions more likely in the table structure.",
